/* =====================================================================
   TSF COMMAND — app core: state, data layer, helpers, shell.
   Data source: the artifact's hosted document store (claude.use('db')).
   Swap point for Supabase: the Data object below.
   ===================================================================== */
'use strict';

const COLLECTIONS = ['vocab', 'rules', 'factions', 'manufacturers', 'models', 'variants', 'equipment', 'gm_notes',
  'pilots', 'tsfs', 'configs', 'approvals', 'service', 'incidents', 'maintenance', 'audit', 'zones', 'missions', 'settings', 'fronts', 'notices', 'revisions', 'units', 'unitlog', 'crews', 'stocklog', 'armoury', 'armourylog', 'contracts', 'orders', 'engagements', 'xplog', 'rpposts', 'supplylines', 'sitreps', 'research', 'researchlog', 'trials', 'evaluations', 'doctrines', 'courses', 'prodlines', 'snapshots', 'journal', 'relations', 'statrolls', 'slots'];
/* Fixed system mounts: propulsion (engines, fuel) and airframe parts. Equipment with an engine profile uses ENGINE_SLOTS. */
const ENGINE_SLOTS = ['jump_unit', 'thruster', 'power_plant', 'fuel'];
const PART_SLOTS = ['armour', 'actuator', 'avionics'];
const SYSTEM_SLOTS = ENGINE_SLOTS.concat(PART_SLOTS);
const inSlots = set => h => h.slots.length > 0 && h.slots.every(s => set.indexOf(s) !== -1);
const isEngineMount = inSlots(ENGINE_SLOTS), isPartMount = inSlots(PART_SLOTS), isSystemMount = inSlots(SYSTEM_SLOTS);
const AFTER_RENDER = [];

const S = {
  phase: 'boot', store: {}, delivered: new Set(), db: null, user: null, uid: null, isGm: false,
  route: 'dashboard', pilotId: null, navOpen: false, navCollapsed: false, isOwner: false, busy: false, readOnly: false,
  ws: { tsfId: null, versionId: null, draft: null, dirty: false, tab: 'loadout' },
  ui: { drawer: null, confirm: null, toast: null, edit: null, form: {}, cat: { tab: 'models', q: '', category: '', manufacturer: '', availability: '', weight: '', compat: '' },
        eq: { q: '', category: '' }, apprFilter: 'pending', svcTsf: null, reason: '' }
};

/* ---------------------------------------------------------------- helpers */
const ESC = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
const esc = s => s == null ? '' : String(s).replace(/[&<>"']/g, c => ESC[c]);
const fmtDate = iso => iso ? new Date(iso).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }) : '–';
const fmtDT = iso => iso ? new Date(iso).toLocaleString('en-GB', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }) : '–';
const nowIso = () => new Date().toISOString();
const newId = p => p + '-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
const clone = o => o == null ? o : JSON.parse(JSON.stringify(o));
/* Need-to-know hook: the access module sets VIEW_FILTER so each character only sees what their clearance allows. */
/* Where uploaded images are served from: the artifact's asset store here, a Supabase Storage bucket when self-hosted. */
const HOSTED = () => typeof window !== 'undefined' && !!window.UNTSF_ACCOUNT;
const isMod = () => HOSTED() && window.UNTSF_ACCOUNT.role === 'mod';
const ASSET_BASE = (typeof window !== 'undefined' && window.UNTSF_ASSET_BASE) || '/_blob/';
let VIEW_FILTER = null, routeAllowed = () => true, sessionExtras = () => '';
const list = col => { const out = Object.keys(S.store[col] || {}).map(id => Object.assign({}, S.store[col][id], { id })); return VIEW_FILTER ? out.filter(d => VIEW_FILTER(col, d)) : out; };
const get = (col, id) => { const d = id && S.store[col] && S.store[col][id] ? Object.assign({}, S.store[col][id], { id }) : null; return d && VIEW_FILTER && !VIEW_FILTER(col, d) ? null : d; };
const vocab = name => TSFModel.vocab(S.store, name);
const signed = n => n > 0 ? '+' + n : n < 0 ? '\u2212' + Math.abs(n) : '0';
const plural = (n, w) => n + ' ' + w + (n === 1 ? '' : 's');
function lsGet(k) { try { return localStorage.getItem(k); } catch (e) { return null; } }
function lsSet(k, v) { try { if (v == null) localStorage.removeItem(k); else localStorage.setItem(k, v); } catch (e) { /* storage unavailable */ } }

function getPath(path) { return path.split('/').reduce((o, k) => (o == null ? undefined : o[k]), S); }
function setPath(path, value) {
  const keys = path.split('/'); let o = S;
  for (let i = 0; i < keys.length - 1; i++) { if (o[keys[i]] == null) o[keys[i]] = {}; o = o[keys[i]]; }
  o[keys[keys.length - 1]] = value;
}

const genName = id => (vocab('generations').find(g => g.id === id) || {}).name || id || '–';
const GEN_SHORT = { '1': '1st gen', '1.5': '1.5 gen', 'q2': 'Quasi-2nd gen', '2': '2nd gen', '2.5': '2.5 gen', 'q3': 'Quasi-3rd gen', '3': '3rd gen' };
const genShort = id => id ? (GEN_SHORT[id] || genName(id)) : '–';
const className = id => (vocab('classifications').find(c => c.id === id) || {}).name || id || '–';
const catName = code => (vocab('categories').find(c => c.code === code) || {}).name || code;
const slotName = code => (vocab('slot_types').find(c => c.code === code) || {}).name || code;
const statDefs = scope => vocab('stats').filter(s => s.scope === scope).sort((a, b) => a.order - b.order);
const statName = code => (vocab('stats').find(s => s.code === code) || {}).name || code;
const rankById = id => vocab('ranks').find(r => r.id === id);
const mfrName = id => (get('manufacturers', id) || {}).name || (id ? id : 'Unattributed');
const facName = id => (get('factions', id) || {}).name || '–';
const activeRules = () => TSFModel.activeRules(S.store);
const effVariant = id => TSFModel.effectiveVariant(S.store, id);
const isWeaponCat = code => !!(vocab('categories').find(c => c.code === code) || {}).isWeapon;

function tsfLabel(t) {
  const v = effVariant(t.variantId);
  return v ? `${v.designation} ${v.modelName}${v.code !== 'STD' ? ' (' + v.name + ')' : ''}` : t.serial;
}
function pilotLabel(p) { return p ? `${p.callsign ? p.callsign + ' · ' : ''}${p.fullName}` : 'Depot stock'; }
function currentPilot() { return get('pilots', S.pilotId); }
function actorLabel() { return S.isGm ? 'GM' : ((currentPilot() || {}).personnelId || 'player'); }
function ownTsfs() {
  const all = list('tsfs');
  return (S.pilotId ? all.filter(t => t.ownerPilotId === S.pilotId) : [])
    .sort((a, b) => (b.isPrimary - a.isPrimary) || a.serial.localeCompare(b.serial));
}
function canTouchTsf(t) { return !!t && (S.isGm || (t.ownerPilotId && t.ownerPilotId === S.pilotId)); }
function activeConfig(t) { return t ? get('configs', t.activeConfigId) : null; }

/* Player-facing catalogue visibility (the Supabase build enforces this with RLS). */
function eqVisible(e) {
  if (S.isGm) return e.publishStatus === 'published';
  if (e.publishStatus !== 'published') return false;
  const p = currentPilot();
  return e.availability !== 'gm_only' || !!(p && p.access && p.access[e.id] && p.access[e.id].access === 'granted');
}
function variantVisible(v) {
  if (!v) return false;
  if (S.isGm) return v.publishStatus === 'published';
  return v.publishStatus === 'published' && v.availability !== 'gm_only';
}

/* ---------------------------------------------------------------- statuses
   TSF statuses and their permitted transitions are data (vocab/tsf_statuses); these are the defaults. */
const TSF_STATUS_DEFAULT = [
  { code: 'operational', label: 'OPERATIONAL', meaning: 'Fully available', tone: 'ok', next: ['standby', 'damaged', 'maintenance', 'restricted', 'retired', 'destroyed'] },
  { code: 'standby', label: 'STANDBY', meaning: 'Available but not assigned to active duty', tone: '', next: ['operational', 'damaged', 'maintenance', 'restricted', 'retired', 'destroyed'] },
  { code: 'maintenance', label: 'MAINTENANCE', meaning: 'Under scheduled maintenance', tone: 'warn', next: ['operational', 'standby', 'damaged', 'restricted', 'destroyed'] },
  { code: 'repair', label: 'REPAIR', meaning: 'Corrective maintenance under way', tone: 'warn', next: ['operational', 'standby', 'damaged', 'restricted', 'destroyed'] },
  { code: 'damaged', label: 'DAMAGED', meaning: 'Operational restrictions apply', tone: 'bad', next: ['repair', 'restricted', 'retired', 'destroyed'] },
  { code: 'restricted', label: 'RESTRICTED', meaning: 'Limited use or access', tone: 'warn', next: ['operational', 'standby', 'damaged', 'maintenance', 'retired', 'destroyed'] },
  { code: 'retired', label: 'RETIRED', meaning: 'No longer active in service', tone: '', next: [] },
  { code: 'destroyed', label: 'DESTROYED', meaning: 'Asset permanently lost', tone: 'bad', next: [] }
];
function tsfStatuses() { const v = vocab('tsf_statuses'); return v.length ? v : TSF_STATUS_DEFAULT; }
function tsfStatus(code) { return tsfStatuses().find(x => x.code === code) || { code, label: String(code || '').toUpperCase(), next: [] }; }
function canTransition(from, to) { return from === to || tsfStatus(from).next.indexOf(to) !== -1; }

const STATUS_CHIP = {
  draft: 'acc', submitted: 'warn', approved: 'ok', rejected: 'bad', changes_requested: 'warn', withdrawn: '',
  pending: 'warn', in_progress: 'warn', completed: 'ok', requested: 'warn',
  standard: '', experimental: 'warn', gm_only: 'bad', public: '', published: 'ok', archived: '', active: 'ok', superseded: '',
  on_hold: 'warn', cancelled: '', critical: 'bad'
};
const STATUS_TEXT = { changes_requested: 'Changes requested', gm_only: 'GM only', in_progress: 'In progress', submitted: 'Pending approval', approved: 'Approved', on_hold: 'On hold', cancelled: 'Cancelled' };
function chip(status, text) {
  const st = TSF_STATUS_DEFAULT.find(x => x.code === status) ? tsfStatus(status) : null;
  const t = text || (st ? st.label : (STATUS_TEXT[status] || (status ? status.replace(/_/g, ' ') : '–')));
  const tone = st ? st.tone : (STATUS_CHIP[status] || '');
  return `<span class="chip ${tone}" ${st ? `title="${esc(st.meaning || '')}"` : ''}>${esc(String(t).toUpperCase())}</span>`;
}

/* ---------------------------------------------------------------- reference codes
   Generated, never typed: PERS-, TSF-, MOD-TSF-, EQP-, CFG-, MNT-, APR-, OPS-. */
function refHash(id) { let h = 2166136261; for (const c of String(id)) { h ^= c.charCodeAt(0); h = Math.imul(h, 16777619) >>> 0; } return String(h % 1000000).padStart(6, '0'); }
const REF = {
  pers: p => p ? 'PERS-' + (String(p.personnelId || '').indexOf('-') !== -1 ? p.personnelId : String(p.personnelId || '').padStart(6, '0')) : '',
  tsf: t => t ? 'TSF-' + refHash(t.id) : '',
  model: m => m ? 'MOD-TSF-' + String(m.designation || '').toUpperCase().replace(/^TYPE-/, '').replace(/[^A-Z0-9]/g, '') : '',
  eqp: e => e ? 'EQP-' + (String(e.code || '').replace(/\D/g, '') || refHash(e.id)).padStart(6, '0') : '',
  cfg: c => c ? 'CFG-' + refHash(c.id) : '', mnt: m => m ? 'MNT-' + refHash(m.id) : '',
  apr: a => a ? 'APR-' + refHash(a.id) : '', ops: m => m ? 'OPS-' + refHash(m.id) : ''
};
const ref = (kind, rec) => `<span class="ref">${esc(REF[kind](rec))}</span>`;

/* ---------------------------------------------------------------- platform identity */
const BRAND = { code: 'UNTSF-COMM', name: 'United Nations Tactical Surface Fighter Command', system: 'Command & Logistics System', security: 'INTERNAL' };
/* Original UNTSF crest (UX-STD-001 §2.2): shield, TSF silhouette, orbital ring, "UNTSF".
   Deliberately not the UN emblem. compact = no lettering, for small sizes. */
function insignia(size, compact) {
  return `<svg class="insignia-brand" viewBox="0 0 64 72" width="${size}" height="${Math.round(size * 72 / 64)}" aria-hidden="true">
    <path d="M32 3 L59 12 L56 44 Q51 62 32 69 Q13 62 8 44 L5 12 Z" fill="none" stroke="currentColor" stroke-width="2.4"/>
    <path d="M32 8 L54 15.5 L51.5 43 Q47 58 32 64 Q17 58 12.5 43 L10 15.5 Z" fill="currentColor" opacity=".08"/>
    <ellipse cx="32" cy="${compact ? 36 : 33}" rx="21" ry="7" fill="none" stroke="#d9a441" stroke-width="1.6" transform="rotate(-18 32 ${compact ? 36 : 33})"/>
    <g transform="translate(0 ${compact ? 3 : 0})">
      <path d="M32 13 L38.5 30 L32 27 L25.5 30 Z" fill="currentColor"/>
      <rect x="30.4" y="28.5" width="3.2" height="15" fill="currentColor"/>
      <path d="M17 34 h10 l2.5 3.8 h-10 Z M47 34 h-10 l-2.5 3.8 h10 Z" fill="currentColor" opacity=".9"/>
      <path d="M27 45 h10" stroke="currentColor" stroke-width="2"/></g>
    ${compact ? '' : `<text x="32" y="57.5" text-anchor="middle" font-family="Rajdhani, Arial Narrow, sans-serif" font-weight="700" font-size="9.5" letter-spacing="1.2" fill="currentColor">UNTSF</text>`}</svg>`;
}
/* Logo formats (§2.1): primary horizontal, compact navigation, light document. */
function logoHtml(format) {
  if (format === 'compact') return `<span class="logo logo-compact">${insignia(30, true)}<span class="logo-code">UNTSF</span></span>`;
  if (format === 'document') return `<div class="logo logo-doc">${insignia(54)}<div><div class="logo-code">UNTSF-COMM</div><div class="logo-sub">TACTICAL SURFACE FIGHTER COMMAND</div></div></div>`;
  return `<span class="logo logo-primary">${insignia(34, true)}<span><span class="logo-un">UNITED NATIONS</span><span class="logo-code">UNTSF-COMM</span></span></span>`;
}

