/* ---------------------------------------------------------------- rules */
route('rules', 'Rules and Balancing', function () {
  const sets = list('rules').sort((a, b) => b.version - a.version);
  const act = activeRules(), draft = sets.find(r => r.status === 'draft');
  if (draft && (!S.ui.edit || S.ui.edit.kind !== 'rules' || S.ui.edit.id !== draft.id)) S.ui.edit = { kind: 'rules', id: draft.id, rs: clone(draft) };
  const e = draft ? S.ui.edit.rs : null, p = 'ui/edit/rs';
  const byVer = {};
  list('configs').filter(c => c.status === 'approved').forEach(c => { byVer[c.ruleSetVersion] = (byVer[c.ruleSetVersion] || 0) + 1; });
  const view = rs => `<dl class="kv"><dt>Stacking</dt><dd>${esc(rs.stacking.replace(/_/g, ' '))}</dd><dt>Upgrades per TSF</dt><dd>${rs.maxUpgrades}</dd>
    <dt>Overall rating</dt><dd>${rs.ratingEnabled ? 'Shown' : 'Hidden'}</dd><dt>Needs approval</dt><dd>${esc(Object.keys(rs.policies).filter(k => rs.policies[k]).join(', ').replace(/_/g, ' '))}</dd></dl>
    ${(() => { const pc = Object.assign({ pointBudget: 330, attrMin: 30, attrMax: 75 }, rs.pilotCreation || {});
      return `<dl class="kv" style="margin-top:8px"><dt>Pilot points</dt><dd>${pc.pointBudget}, each ${pc.attrMin}–${pc.attrMax}</dd><dt>Starting rank</dt><dd>${esc((rankById(pc.startingRankId) || {}).name || 'None')}</dd>
      <dt>Starting TSF</dt><dd>${esc(pc.initialVariantId ? tsfLabelFromVariant(pc.initialVariantId) : 'None, pilots request one')}</dd></dl>`; })()}
    <table class="data" style="margin-top:10px"><thead><tr><th>Statistic</th><th class="num">Min</th><th class="num">Max</th><th class="num">Rating weight</th></tr></thead>
    <tbody>${vocab('stats').filter(s => s.scope === 'tsf').map(s => `<tr><td>${esc(s.name)}</td><td class="num">${rs.limits[s.code].min}</td><td class="num">${rs.limits[s.code].max}</td><td class="num">${rs.limits[s.code].weight}</td></tr>`).join('')}</tbody></table>`;
  return `<div class="page-head"><div><h1>Rules and Balancing</h1><p>Rules are versioned. Changing them never rewrites an approved configuration; those keep the statistics frozen when they were approved.</p></div>
    ${!draft ? `<button class="btn primary" data-act="rules-draft">Draft new rules from v${act.version}</button>` : ''}</div>
    <div class="grid g2"><div class="plate"><h2>Active: v${act.version} ${esc(act.label)} <span class="sub">since ${fmtDate(act.activatedAt)}</span></h2>${view(act)}</div>
    ${draft ? `<div class="plate"><h2>Draft v${e.version}</h2><div class="form-grid"><label class="field">Label${txt('r-label', p + '/label', e.label)}</label>
      <label class="field">Modifier stacking${sel('r-stack', p + '/stacking', e.stacking, [['additive', 'Additive'], ['highest_per_stat', 'Highest bonus per stat'], ['diminishing', 'Diminishing returns']])}</label>
      <label class="field">Upgrades per TSF${num('r-up', p + '/maxUpgrades', e.maxUpgrades)}</label>
      <label class="field">Overall rating${sel('r-rate', p + '/ratingEnabled', String(e.ratingEnabled), [['true', 'Shown'], ['false', 'Hidden']])}</label></div>
      <h3 style="margin:14px 0 6px">Limits and weights</h3><table class="data"><thead><tr><th>Statistic</th><th>Min</th><th>Max</th><th>Weight</th></tr></thead><tbody>
      ${vocab('stats').filter(s => s.scope === 'tsf').map(s => `<tr><td>${esc(s.name)}</td><td>${num('r-' + s.code + '-min', p + '/limits/' + s.code + '/min', e.limits[s.code].min)}</td>
        <td>${num('r-' + s.code + '-max', p + '/limits/' + s.code + '/max', e.limits[s.code].max)}</td><td><input type="number" step="0.05" id="r-${s.code}-w" data-bind="${p}/limits/${s.code}/weight" data-type="number" value="${e.limits[s.code].weight}"></td></tr>`).join('')}</tbody></table>
      ${(() => { e.pilotCreation = Object.assign({ pointBudget: 330, attrMin: 30, attrMax: 75, startingRankId: 'r-2lt', initialVariantId: null }, e.pilotCreation || {}); const pc = e.pilotCreation, q = p + '/pilotCreation';
        return `<h3 style="margin:14px 0 6px">Pilot creation</h3><div class="row-edit"><label class="field">Point budget${num('r-pc-b', q + '/pointBudget', pc.pointBudget)}</label>
        <label class="field">Attribute min${num('r-pc-min', q + '/attrMin', pc.attrMin)}</label><label class="field">Attribute max${num('r-pc-max', q + '/attrMax', pc.attrMax)}</label></div>
        <div class="form-grid"><label class="field">Starting rank${sel('r-pc-rank', q + '/startingRankId', pc.startingRankId || '', vocab('ranks').map(r => [r.id, r.name]), 'None')}</label>
        <label class="field">Starting TSF${sel('r-pc-var', q + '/initialVariantId', pc.initialVariantId || '', list('variants').map(v => [v.id, tsfLabelFromVariant(v.id)]), 'None, pilots request one')}</label></div>`; })()}
      <h3 style="margin:14px 0 6px">Changes that need GM approval</h3><div class="checks">${Object.keys(e.policies).map(k => `<label><input type="checkbox" data-act="toggle-bool" data-path="${p}/policies/${k}" ${e.policies[k] ? 'checked' : ''}> ${esc(k.replace(/_/g, ' '))}</label>`).join('')}</div>
      <div class="btn-row" style="margin-top:14px"><button class="btn" data-act="rules-save">Save draft</button><button class="btn primary" data-act="rules-activate">Activate v${e.version}</button><button class="btn danger" data-act="rules-delete">Delete draft</button></div></div>` : ''}
    </div>
    <div style="margin-top:16px">${modulesPanel()}</div>
    <div class="plate" style="margin-top:16px"><h2>Version history</h2><table class="data"><thead><tr><th>Version</th><th>Label</th><th>Status</th><th>Activated</th><th class="num">Approved configurations under it</th></tr></thead><tbody>
    ${sets.map(r => `<tr><td>v${r.version}</td><td>${esc(r.label)}</td><td>${chip(r.status)}</td><td>${fmtDate(r.activatedAt)}</td><td class="num">${byVer[r.version] || 0}</td></tr>`).join('')}</tbody></table></div>`;
});

