  const z = list('zones').filter(x => x.status !== 'archived').map(x => ({ x, d: Math.hypot(x.lon - mid[0], x.lat - mid[1]) })).sort((a, b) => a.d - b.d)[0];
  ACTIONS['mission-new']({ zone: z ? z.x.id : null });
  const r = supplyRules(), m = S.ui.edit.m;
