  m.objective = `Keep the ${(r.modes[l.mode] || l.mode).toLowerCase()} from ${l.from || '?'} to ${l.to || '?'} open.`;
  m.briefing = `${l.name} is ${lineStatus(l).label.toLowerCase()} (pressure ${lineStatus(l).pressure}). Threats: ${(l.threats || []).map(t => (r.threats[t.type] || {}).label || t.type).join(', ') || 'none confirmed'}.`;
