ACTIONS['course-save'] = () => {
  const e = S.ui.edit, c = clone(e.c), id = c.id, r = evalRules();
  if (!c.title.trim() || !c.subjectId) { toast('Name the course and choose what it teaches.', true); return; }
  if (!c.qualification.trim()) c.qualification = c.kind === 'doctrine' ? get('doctrines', c.subjectId).qualification : `Trained: ${get('equipment', c.subjectId).name}`;
  if (c.traineeIds.length > c.instructorIds.length * r.traineesPerInstructor) { toast(`Too many trainees: ${r.traineesPerInstructor} per instructor.`, true); return; }
  c.title = c.title.trim(); c.weeks = Math.max(1, Math.round(Number(c.weeks) || 1)); delete c.id;
  run(async () => { await Data.put('courses', id, c); await auditDiff(e.isNew ? 'course.create' : 'course.update', 'course', id, `${e.isNew ? 'Planned' : 'Updated'} ${c.title}`, e.isNew ? {} : S.store.courses[id], c); S.ui.drawer = null; }, 'Course saved.');
};
ACTIONS['course-start'] = () => {
  const id = S.ui.edit.c.id, c = clone(S.store.courses[id]);
  if (!c.instructorIds.length || !c.traineeIds.length) { toast('A course needs at least one instructor and one trainee.', true); return; }
  c.status = 'running'; c.startedOn = campaignDate(); c.weeksDone = 0;
  run(async () => { await Data.put('courses', id, c);
    if (c.restrict && c.kind === 'equipment') { const e = clone(S.store.equipment[c.subjectId]); if (!(e.unlock || []).some(u => u.qualification === c.qualification)) { e.unlock = (e.unlock || []).concat([{ minRank: null, factionId: null, qualification: c.qualification }]); await Data.put('equipment', c.subjectId, e); }
      for (const pid of c.instructorIds) await giveQual(pid, c.qualification); }
    await Data.audit('course.start', 'course', id, `Course started: ${c.title}`); S.ui.drawer = null; }, 'Course started.');
};
async function advanceCourses(days) {
  const r = evalRules(), out = [];
  for (const c0 of list('courses').filter(c => c.status === 'running')) {
    const c = clone(S.store.courses[c0.id]); c.weeksDone = Math.min(c.weeks, (c.weeksDone || 0) + days / 7);
    if (c.weeksDone >= c.weeks) {
      c.status = 'complete';
      for (const pid of c.traineeIds) { await giveQual(pid, c.qualification); await awardXp(pid, r.graduateXp, `Graduated: ${c.title}`, 'award'); await checkQualifications(pid); }
      for (const pid of c.instructorIds) await awardXp(pid, r.instructorXp, `Instructed: ${c.title}`, 'award');
      await Data.put('notices', newId('ntc'), { at: nowIso(), priority: 'routine', title: `Course complete: ${c.title}`, body: `${plural(c.traineeIds.length, 'pilot')} qualified: ${c.qualification}.` });
      out.push(`${c.title}: complete, ${plural(c.traineeIds.length, 'graduate')}.`);
    } else out.push(`${c.title}: ${Math.floor(c.weeksDone)} of ${c.weeks} weeks.`);
    await Data.put('courses', c0.id, c);
  }
  return out;
}

