    if (lv.callsign && sp.callsign) decal(g => { g.fillStyle = lv.accent; g.font = '700 70px Rajdhani, sans-serif'; g.textAlign = 'center'; g.fillText(sp.callsign.toUpperCase(), 128, 82); }, 1.1, 0.35, 0, 1.45, -0.48 * b - 0.01, Math.PI);
    if (lv.killMarks && sp.kills) decal(g => { g.fillStyle = lv.accent; for (let i = 0; i < Math.min(40, sp.kills); i++) g.fillRect(14 + (i % 10) * 23, 14 + Math.floor(i / 10) * 30, 12, 22); }, 0.5, 0.25, 0.38 * b, -0.7, 0.32 * b + 0.01);
