  const who = r => r.toPilotId ? (q => q ? `${avatarHtml(q, 40)}<div><b>${linkEishi(q)}</b><br><span class="small muted">${esc(q.fullName)}</span></div>` : '<div><b>Unknown</b></div>')(get('pilots', r.toPilotId) || S.store.pilots[r.toPilotId]) : `<span class="npc-avatar">${esc((r.npcName || '?').slice(0, 2).toUpperCase())}</span><div><b>${esc(r.npcName)}</b><br><span class="small muted">Not a player character</span></div>`;
