/* ---------------------------------------------------------------- the record */
const RECORD_SECTIONS = [['service', 'Service record', 'pilot.service'], ['attributes', 'Attributes', 'pilot.attributes'], ['qualifications', 'Qualifications, courses and awards', 'pilot.qualifications'],
  ['tsfs', 'Assigned TSFs', null], ['timeline', 'Service timeline', 'pilot.career'], ['background', 'Background', 'pilot.background'], ['relationships', 'Relationships (public)', 'pilot.relationships']];
const sectionOffered = key => { const s = RECORD_SECTIONS.find(x => x[0] === key); if (S.isGm && !S.ui.previewAs) return true; return key === 'tsfs' ? routeAllowed('hangar') : !s[2] || sectionAllowed(s[2]); };
