    + para(p.fullName, { style: 'Title' })
    + para(`${rk ? rk.name + ' ' : ''}${p.callsign ? '“' + p.callsign + '”' : ''}${p.callsign || rk ? ' · ' : ''}Eishi · ${roleLabel(p.unitRole)} · ${chain}`, { color: '4C5B67', after: 0 });
