  const zone = chain.slice().reverse().map(u => u.homeZoneId && get('zones', u.homeZoneId)).find(Boolean);
  const short = t => String(t || '').replace(/\bSquadron\b/i, 'Sqn').replace(/\bBattalion\b/i, 'Bn').replace(/\bCompany\b/i, 'Coy');
