ROUTE_DEPT.applications = 'PERS'; ROUTES.applications.dept = 'PERS';
ACTIONS['apps-refresh'] = () => loadAppDrafts();
ACTIONS['draft-view'] = d => { S.ui.form.draftView = { key: d.key, uid: d.uid }; openDrawer('draft-view'); };
DRAWERS_REG('draft-view', function () {
  const v = S.ui.form.draftView, rec = v && (APPS.list || []).find(r => r.key === v.key && r.uid === v.uid), x = rec && draftSummary(rec);
  if (!x) return `<header><div><h2>Application</h2><p>This draft is no longer there: it may have been sent or discarded.</p></div><button class="btn ghost" data-act="close-drawer" aria-label="Close">${icon('x')}</button></header>`;
  const d = x.d, fac = d.factionId ? facName(d.factionId) : '', age = (() => { try { return d.dob ? ageAt(birthOf(d.dob), settingDate()) : null; } catch (e) { return null; } })();
  const row = (l, val) => val || val === 0 ? `<dt>${esc(l)}</dt><dd>${esc(String(val))}</dd>` : '';
  const choices = (d.postingChoices || []).map(id => { const sl = get('slots', id); return sl ? sl.title + (get('units', sl.unitId) ? ' · ' + get('units', sl.unitId).name : '') : null; }).filter(Boolean);
  const text = (l, t) => t && String(t).trim() ? `<h3>${esc(l)}</h3><p style="white-space:pre-wrap">${esc(String(t).length > 900 ? String(t).slice(0, 900) + ' …' : t)}</p>` : '';
  return `<div class="wide-drawer"></div><header><div><p class="kicker">APPLICATION IN PROGRESS · ${esc(playerName(x.uid))}</p><h2>${esc(d.callsign ? d.callsign + ' · ' : '')}${esc(d.fullName || 'Unnamed')}</h2>
      <p>${x.pilot ? 'Revising after changes were requested. ' : ''}Last saved ${x.savedAt ? esc(fmtDT(x.savedAt)) : '–'}. Read only: the player is still writing it.</p></div><button class="btn ghost" data-act="close-drawer" aria-label="Close">${icon('x')}</button></header>
    <div class="body"><div style="display:flex;flex-wrap:wrap;gap:16px;align-items:flex-start">
      ${d.portraitAssetId ? `<img src="${ASSET_BASE}${esc(d.portraitAssetId)}" alt="Portrait" style="width:150px;height:190px;object-fit:cover;border-radius:4px;border:1px solid var(--line)">` : ''}
      <dl class="kv" style="flex:1 1 260px">${row('Kind', d.kind === 'support' ? 'Support staff' : 'Eishi')}${row('Date of birth', d.dob ? d.dob + (age != null ? ` (age ${age} in ${settingYear()})` : '') : '')}${row('Nationality', d.nationality)}${row('Born in', d.birthplace)}
        ${row('Native name', d.nativeName)}${row('Discord', d.discord)}${row('Serves with', fac)}${row('Years of service', d.yearsService)}${row('Face claims', [d.fcIrl, d.fcAnime].filter(Boolean).join(' · '))}${row('Posting wanted', choices.join('; '))}</dl></div>
      <section><h3>Progress · ${x.done} of ${x.total} sections complete</h3><ul class="small" style="margin:6px 0 0;padding-left:18px">${x.steps.map(s => `<li>${s.pr.length ? '○' : '✓'} <b>${esc(s.l)}</b>${s.pr.length ? ` · <span class="muted">${esc(s.pr[0])}</span>` : ''}</li>`).join('')}</ul></section>
      ${text('Motivation', d.motivation)}${text('Biography', d.biography)}${text('Personality', d.personality)}</div>`;
});
/* ---------------------------------------------------------------- TSF Directory (applicants)
   Anyone applying (writing an application, or waiting on a decision) can browse the TSF line-up to see the variety
   on offer: the same frames and specifications players see, with nothing to request or change. */
function tsfDirectoryView() {
  const html = catalogueView('models').replace(/<button class="btn primary" data-act="open-drawer" data-type="acquire">[\s\S]*?<\/button>/, '');
  const back = S.isGm ? '' : `<button class="btn" data-act="nav" data-route="dashboard">${S.ui.enlisting ? 'Back to my application' : S.pilotId ? 'Back' : 'Back to applying'}</button>`;
  return html.replace(/<div class="page-head"><div><h1>Equipment Catalogue<\/h1><p>[\s\S]*?<\/p><\/div>/,
    `<div class="page-head"><div><p class="kicker">UNTSF-COMM · TSF DIRECTORY</p><h1>TSF Directory</h1><p>The frames in service with this command. Select one to read its specification. This is a look only: machines are issued once you’re accepted.</p></div>${back}`);
}
route('tsf-directory', 'TSF Directory', tsfDirectoryView, { shared: true });
const _mainHtmlDir = mainHtml;
mainHtml = function () { return S.route === 'tsf-directory' ? tsfDirectoryView() : _mainHtmlDir(); };
/* In the directory the specification drawer is read only. */
const _variantDrawerDir = DRAWERS.variant;
DRAWERS_REG('variant', d => {
  const html = _variantDrawerDir(d);
  if (S.route !== 'tsf-directory') return html;
  return html.replace(/<button[^>]*data-act="(doc|acquire-submit|acq-pick|unlock-request)"[^>]*>[\s\S]*?<\/button>/g, '')
    .replace(/<button[^>]*data-type="acquire"[^>]*>[\s\S]*?<\/button>/g, '');
});
['doc', 'acquire-submit', 'acq-pick', 'unlock-request'].forEach(n => { const o = ACTIONS[n]; if (o) ACTIONS[n] = (d, el) => S.route === 'tsf-directory' && !S.isGm ? undefined : o(d, el); });
/* Ways in: the Apply screen, the application itself, and the waiting screen. */
const DIR_BTN = () => `<button class="btn" data-act="nav" data-route="tsf-directory">${icon('eye', 16)} Browse the TSF directory</button>`;
const _enlistViewDir = enlistView;
enlistView = function () { return `<div class="btn-row" style="justify-content:flex-end;margin-bottom:8px">${DIR_BTN()}</div>` + _enlistViewDir.apply(this, arguments); };
const _appStatusDir = applicationStatusView;
applicationStatusView = function (p) { return _appStatusDir(p) + `<div class="btn-row" style="margin-top:12px">${DIR_BTN()}</div>`; };
const _claimViewDir = claimView;
claimView = function () { const h = _claimViewDir.apply(this, arguments); return h + `<div class="btn-row" style="margin-top:16px">${DIR_BTN()}</div>`; };
UPLOAD_TARGETS['unit-art'] = id => { S.ui.edit.u.insigniaAssetId = id; };
;
/* ---------------------------------------------------------------- operation updates on Discord
   Map posts go to a channel of their own: one named for operations (DISCORD_WEBHOOK_OPERATIONS in Cloudflare) unless
   Command Authority picks another, which is then remembered. Posting a situation report offers to send it with the map. */
function opsChannelFor(ds) {
  const want = discordSettings().mapChannel;
  return want && ds.channels.indexOf(want) !== -1 ? want : ds.channels.find(c => /operation|ops|sitrep|map/.test(c)) || ds.channels[0];
}
function rememberMapChannel(channel) {
  const cfg = discordSettings(); if (cfg.mapChannel === channel) return;
  const next = Object.assign({}, cfg, { mapChannel: channel }); delete next.id;
  Data.put('settings', 'discord', next).catch(() => {});
}
const _briefOpenOps = ACTIONS['brief-open'];
ACTIONS['brief-open'] = d => {
  _briefOpenOps(d);
  const f = S.ui.form.brief; if (!f || f.kind !== 'map') return;
  if (d.message) f.message = d.message;
  f.level = Number(d.level) || 0; f.update = !!d.update;
  if (S.isGm) discordReady().then(ok => { if (ok && S.ui.form.brief === f && !f.channel) { f.channel = opsChannelFor(S.discordState); render(); } });
};
/* Posting a report: share it, with the map as it's shown now, unless the box beside Post is unticked. */
const _sitrepPostOps = ACTIONS['sitrep-post'];
ACTIONS['sitrep-post'] = () => {
  const t = (S.ui.form.sitrep || '').trim(), lvl = Number(S.ui.form.sitrepLevel || 0), share = S.ui.form.sitrepDiscord !== false;
  _sitrepPostOps();
  if (!t || !S.isGm || !share) return;
  discordReady().then(ok => { if (ok) ACTIONS['brief-open']({ kind: 'map', mode: 'gm', update: true, level: lvl, message: `📡 **Operation update** · ${fmtCampaign(campaignDate())}\n${t}`.slice(0, 1900) }); });
};
ACTIONS['sitrep-discord'] = () => { S.ui.form.sitrepDiscord = S.ui.form.sitrepDiscord === false; render(); };
const _situationOps = ROUTES.situation.view;
ROUTES.situation.view = function () {
  const html = _situationOps.apply(this, arguments);
  if (!S.isGm || S.ui.previewAs) return html;
  ensureDiscord();
  if (!S.discordState || S.discordState.status !== 'ready') return html;
  return html.replace('<button class="btn" data-act="sitrep-post">Post</button>', `<button class="btn" data-act="sitrep-post">Post</button>
    <label class="small" style="align-self:center"><input type="checkbox" data-act="sitrep-discord" ${S.ui.form.sitrepDiscord !== false ? 'checked' : ''}> Share on Discord with the map</label>`);
};
